def evaluate(current_reputation, observation, my_history, round_num):
    # Sigmoid-based weight increasing with round
    alpha = 1 / (1 + math.exp(-0.4 * (round_num - 6)))
    weight = 0.1 + 0.8 * alpha  # range [0.1, 0.9]
    if observation['action'] == 'cooperate':
        delta = weight
    else:
        delta = -weight * 1.1
    # Clamp to [-1, 1]
    return max(-1.0, min(1.0, delta))

def decide(recipient_reputation, round_num, my_history):
    # Base threshold based on round
    if round_num < 5:
        base = -0.2
    elif round_num < 10:
        base = 0.3
    else:
        base = 0.5
    # Adjust based on own cooperation history
    if len(my_history) > 0:
        coop_count = sum(1 for d in my_history if d.get('action') == 'cooperate')
        coop_ratio = coop_count / len(my_history)
    else:
        coop_ratio = 0.5
    # Own cooperation bias: if we've been cooperative, be more trusting
    threshold = base - (coop_ratio - 0.5) * 0.4
    return recipient_reputation > threshold
